record.field:
p = payload or {}
obra_txt = (p.get('obra') or '').strip()
uid = p.get('uid') or ''
fecha = p.get('fecha') or False
bot = env.ref('base.partner_root').id
rec = record
# El mismo recorrido mandado con OTRA fecha es un recorrido nuevo: no se sobrescribe el historial.
if rec.x_envios and fecha and rec.x_fecha and str(rec.x_fecha) != fecha:
    key = '%s-%s' % (uid, fecha)
    rec = model.search([('x_app_uid', '=', key)], limit=1) or model.create({'x_name': 'Recorrido', 'x_app_uid': key})

def num(k):
    try:
        return int(p.get(k) or 0)
    except Exception:
        return 0
rojo, amarillo, azul, verde = num('rojo'), num('amarillo'), num('azul'), num('verde')
total = rojo + amarillo + azul + verde

# Obra: se busca por nombre; si no existe se crea (En curso) y se intenta ligar a una cotización.
Obra = env['x_automa_obra']
obra = rec.x_obra_id
# Plano bajado de Odoo: la app manda la orden de venta, así se liga sin depender del nombre.
orden = env['sale.order']
try:
    orden = env['sale.order'].browse(int(p.get('order_id') or 0)).exists()
except Exception:
    pass
if not obra and orden:
    obra = Obra.search([('x_order_id', '=', orden.id)], limit=1)
    if not obra:
        obra = Obra.create({'x_name': obra_txt or orden.client_order_ref or orden.partner_id.name or orden.name, 'x_estado': 'curso', 'x_order_id': orden.id, 'x_partner_id': orden.partner_id.id})
if not obra and obra_txt:
    obra = Obra.search([('x_name', '=ilike', obra_txt)], limit=1)
    if not obra:
        # Nombre mal escrito que ya se corrigió antes: usa la obra a la que se movió ese recorrido.
        obra = env['x_automa_recorrido'].search([('x_obra', '=ilike', obra_txt), ('x_obra_id', '!=', False), ('id', '!=', rec.id)], order='id desc', limit=1).x_obra_id
    if not obra:
        vo = {'x_name': obra_txt, 'x_estado': 'curso'}
        SO = env['sale.order']
        orders = SO.search([('name', '=ilike', obra_txt)], limit=2)
        if not orders:
            orders = SO.search(['|', '|', ('client_order_ref', 'ilike', obra_txt), ('partner_id.name', 'ilike', obra_txt), ('name', 'ilike', obra_txt)], order='date_order desc', limit=2)
        if len(orders) == 1:
            vo['x_order_id'] = orders.id
            vo['x_partner_id'] = orders.partner_id.id
        obra = Obra.create(vo)

vals = {
    'x_name': ('Recorrido %s %s %s' % (obra_txt, (p.get('plano') or '').strip(), fecha or '')).replace('  ', ' ').strip(),
    'x_obra': obra_txt,
    'x_fecha': fecha,
    'x_tecnico': (p.get('tecnico') or '').strip(),
    'x_plano': (p.get('plano') or '').strip(),
    'x_rojo': rojo, 'x_amarillo': amarillo, 'x_azul': azul, 'x_verde': verde,
    'x_total': total,
    'x_pct_cableado': round(100.0 * (azul + verde) / total, 1) if total else 0.0,
    'x_pct_terminado': round(100.0 * verde / total, 1) if total else 0.0,
    'x_envios': (rec.x_envios or 0) + 1,
}
if obra:
    vals['x_obra_id'] = obra.id
    if obra.x_order_id and not rec.x_order_id:
        vals['x_order_id'] = obra.x_order_id.id
        vals['x_partner_id'] = obra.x_partner_id.id
adjuntos = []
if p.get('pdf'):
    if rec.x_pdf:
        # Corrección del mismo día: el PDF anterior queda en el historial.
        old = env['ir.attachment'].create({'name': 'Anterior - ' + (rec.x_pdf_name or 'recorrido.pdf'), 'datas': rec.x_pdf, 'res_model': 'x_automa_recorrido', 'res_id': rec.id, 'mimetype': 'application/pdf'})
        adjuntos = [old.id]
    vals['x_pdf'] = p.get('pdf')
    vals['x_pdf_name'] = p.get('archivo') or 'Recorrido.pdf'

nuevo = not rec.x_envios
rec.write(vals)
resumen = 'Falta tubería %s · Detalle %s · Cableado OK %s · Terminado %s (%s salidas)' % (rojo, amarillo, azul, verde, total)
rec.message_post(body=('Recorrido recibido de la app' if nuevo else 'Recorrido corregido desde la app (el PDF anterior queda adjunto)') + ': ' + resumen, author_id=bot, attachment_ids=adjuntos)
quien = '%s del %s (%s): %s' % ('Nuevo recorrido' if nuevo else 'Recorrido corregido', fecha or '', vals['x_tecnico'] or 'técnico', resumen)
if obra:
    obra.message_post(body=quien, author_id=bot)
if rec.x_order_id:
    rec.x_order_id.message_post(body=quien, author_id=bot)
